function draw({board,width,height,progress,params}) {
 const P=VisualBook.palette, k=Number(params.k), cell=width<500?23:36;
 const sx=(width-12*cell)/2, sy=83, target=44, tx=(width-4*target)/2, ty=116;
 board.text('start','x · (12,)',20,28,{size:16,color:P.ink});
 board.text('end','X · (3, 4)',width-20,28,{size:16,anchor:'end',color:P.ink});
 board.text('count','12 个元素 · 顺序不变',width/2,55,{size:14,anchor:'middle',color:P.muted});
 board.text('axis1','轴 1 · 列 →',width-20,120,{size:13,anchor:'end',color:P.muted});
 board.text('axis0','轴 0',tx-16,181,{size:13,anchor:'end',color:P.muted,opacity:progress});
 board.text('axis0b','行 ↓',tx-16,201,{size:13,anchor:'end',color:P.muted,opacity:progress});
 const positions=[], vertical=VisualBook.clamp(progress/.45,0,1), horizontal=VisualBook.clamp((progress-.45)/.55,0,1);
 for(let n=0;n<12;n++) {
  const r=Math.floor(n/4),c=n%4,x=VisualBook.mix(sx+n*cell,tx+c*target,horizontal),y=sy+r*target*vertical+(ty-sy)*horizontal,s=VisualBook.mix(cell-2,target-4,horizontal);
  const active=n===k; positions.push([x,y]);
  board.rect('element-'+n,x,y,s,s,active?P.blue:P.faint,{rx:3,stroke:active?P.blue:'#d7dedf','stroke-width':1});
  board.text('value-'+n,String(n),x+s/2,y+s/2+5,{size:14,anchor:'middle',color:active?'#ffffff':P.ink});
 }
 const r=Math.floor(k/4),c=k%4;
 board.text('index','k = '+k+'  →  行 '+r+' · 列 '+c,width/2,height-35,{size:16,anchor:'middle',color:P.blue});
 board.text('rule','k = 4 × 行 + 列',width/2,height-10,{size:14,anchor:'middle',color:P.muted});
 return {values:Array.from({length:12},(_,i)=>i),inputShape:[12],outputShape:[3,4],count:12,selected:{k,row:r,col:c},progress,positions,convention:'行优先元素位置连续插值；中间帧不代表新的张量形状。'};
}

function draw({board,width,height,params,state,controls}) {
 const P=VisualBook.palette, mobile=width<500, s=mobile?40:48, pick=state.pick||[1,1], r=pick[0], c=pick[1];
 const a=[0,1,2],b=[0,Number(params.b1)],C=a.map(v=>b.map(w=>v+w));
 const ax=mobile?24:width*.11, ay=mobile?112:83, bx=mobile?width*.52:width*.38, by=mobile?42:83, cx=mobile?width*.52:width*.70, cy=mobile?112:83;
 function cell(id,x,y,v,color,active,fn,aria) {
  const node=board.rect(id,x,y,s-3,s-3,active?color:P.faint,{rx:3,stroke:active?color:'#d7dedf','stroke-width':1});
  board.text(id+'-text',String(v),x+(s-3)/2,y+(s-3)/2+5,{size:16,anchor:'middle',color:active?'#ffffff':P.ink});
  if(fn) board.selectable(node,{label:aria,selected:active,onSelect:fn});
 }
 board.text('a-label','a · (3, 1)',ax,ay-15,{size:14,color:P.blue});
 board.text('b-label','b · (1, 2)',bx,by-15,{size:14,color:P.orange});
 board.text('c-label','a + b · (3, 2)',cx,cy+3*s+14,{size:14,color:P.ink});
 for(let i=0;i<3;i++) cell('a-'+i,ax,ay+i*s,a[i],P.blue,i===r);
 for(let j=0;j<2;j++) cell('b-'+j,bx+j*s,by,b[j],P.orange,j===c);
 for(let i=0;i<3;i++) for(let j=0;j<2;j++) cell('c-'+i+'-'+j,cx+j*s,cy+i*s,C[i][j],P.ink,i===r&&j===c,()=>controls.setState('pick',[i,j]),'结果第 '+i+' 行，第 '+j+' 列');
 if(mobile) {
  board.line('row-link',ax+s+4,ay+r*s+s/2,cx-5,cy+r*s+s/2,P.blue,2,.65);
  board.line('col-link',bx+c*s+s/2,by+s+4,cx+c*s+s/2,cy-5,P.orange,2,.65);
 } else {
  board.path('row-link',[[ax+s+4,ay+r*s+s/2],[cx-18,ay+r*s+s/2],[cx-5,cy+r*s+s/2]],{color:P.blue,width:2,opacity:.65});
  board.path('col-link',[[bx+c*s+s/2,by-5],[bx+c*s+s/2,by-35],[cx+c*s+s/2,by-35],[cx+c*s+s/2,cy-5]],{color:P.orange,width:2,opacity:.65});
 }
 board.text('axis','行 i ↓   ·   列 j →',width/2,height-82,{size:13,anchor:'middle',color:P.muted});
 board.text('equation','C['+r+','+c+'] = a['+r+',0] + b[0,'+c+']',width/2,height-55,{size:15,anchor:'middle',color:P.ink});
 board.text('numbers',a[r]+' + '+b[c]+' = '+C[r][c],width/2,height-28,{size:20,anchor:'middle',color:P.ink});
 return {a:a.map(x=>[x]),b:[b],output:C,inputShapes:[[3,1],[1,2]],outputShape:[3,2],selected:{row:r,col:c,leftIndex:[r,0],rightIndex:[0,c],sum:C[r][c]},convention:'展示逻辑索引复用，不代表物理复制或内存测量。'};
}

function draw({board,width,height,params}) {
 const P=VisualBook.palette, mobile=width<500, step=Number(params.step),shared=[0,step>=4?9:1,2],copied=[0,1,2];
 const lines=['X = torch.arange(3)','A = X.numpy()','B = torch.tensor(A)','A[1] = 9'];
 const lx=20,ly=mobile?40:79,dy=mobile?28:36,lw=mobile?width-40:width*.43;
 board.text('code-head','逐句观察',lx,ly-23,{size:14,color:P.muted});
 for(let i=0;i<4;i++) {
  board.rect('code-bg-'+i,lx-4,ly+i*dy-19,lw,26,i+1===step?P.faint:'transparent',{rx:2});
  board.text('line-no-'+i,String(i+1),lx,ly+i*dy,{size:13,color:P.muted});
  board.text('line-'+i,lines[i],lx+24,ly+i*dy,{size:13,family:'monospace',color:i+1<=step?P.ink:P.muted,opacity:i+1<=step?1:.55});
 }
 const nx=mobile?20:width*.51, mx=mobile?width-132:width*.72, y=mobile?224:82,cell=34;
 board.text('buffer-head','底层缓冲区',mx,y-28,{size:14,color:P.muted});
 board.text('x-label','X · Tensor',nx,y+18,{size:14,color:P.blue});
 board.path('x-link',[[nx+90,y+14],[mx-12,y+17],[mx-3,y+17]],{color:P.blue,width:1.5});
 board.matrix('shared',[shared],{x:mx,y,cell,activeCell:step>=4?[0,1]:undefined,color:P.blue,precision:0});
 board.text('shared-title',step>=2?'共享':'X 的缓冲区',mx,y-7,{size:13,color:P.blue});
 if(step>=2) {
  board.text('a-label','A · ndarray',nx,y+68,{size:14,color:P.blue});
  board.path('a-link',[[nx+90,y+64],[mx-20,y+45],[mx-3,y+17]],{color:P.blue,width:1.5});
 }
 if(step>=3) {
  board.text('b-label','B · Tensor',nx,y+118,{size:14,color:P.orange});
  board.path('b-link',[[nx+90,y+114],[mx-12,y+117],[mx-3,y+117]],{color:P.orange,width:1.5});
  board.matrix('copy',[copied],{x:mx,y:y+100,cell,color:P.orange,precision:0});
  board.text('copy-title','复制',mx,y+93,{size:13,color:P.orange});
 }
 const values=['X[1] = '+shared[1]];if(step>=2) values.push('A[1] = '+shared[1]);if(step>=3) values.push('B[1] = 1');
 board.text('values',values.join('   ·   '),width/2,height-22,{size:mobile?13:16,anchor:'middle',color:P.ink});
 return {step,lines,sharedBuffer:shared,copyBuffer:step>=3?copied:null,bindings:{X:'shared',...(step>=2?{A:'shared'}:{}),...(step>=3?{B:'copy'}:{})},convention:'有限语义演示。X 和 A 是不同类型对象，连接指向底层存储；不模拟真实地址或分配大小。'};
}
